INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT149-S4-Q14$batch02$, 149, 4, 14, $batch02$Flaw$batch02$, $batch02$Columnist: Wildlife activists have proposed that the practice of stringing cable TV lines from the same poles that carry electric power lines should be banned because cable TV lines, while electrically neutral themselves, make it easier for animals to climb near electric power lines, risking electrocution. This particular argument for banning the practice fails, however, since some animals are electrocuted by power lines even where cable TV lines are all underground.$batch02$, $batch02$Which one of the following most accurately describes a flaw in the columnist’s reasoning?$batch02$, $batch02$B$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=149 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT149-S4-Q14$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$It takes a sufficient condition for an argument’s being inadequate to be a necessary condition for its being inadequate.$batch02$, $batch02$Wrong Flaw$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT149-S4-Q14$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$It rejects an argument for a proposal merely on the grounds that the proposal would not completely eliminate the problem it is intended to address.$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT149-S4-Q14$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$It fails to consider the additional advantageous effects that a proposal to address a problem might have.$batch02$, $batch02$Out of Scope$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT149-S4-Q14$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$It rejects an argument by criticizing the argument’s proponents rather than by criticizing its substance.$batch02$, $batch02$Not Ad Hominem$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT149-S4-Q14$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$It rejects a proposal to address a problem merely on the grounds that other proposals to address the problem would also be effective.$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT149-S4-Q14$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT149-S4-Q14$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$The activists' argument for the ban fails.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$Some animals are electrocuted even where cable lines are underground.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$The activists claim the cable lines make electrocution *easier*, so removing them would reduce it. The columnist answers that electrocution still happens without them. So what? Seat belts do not prevent every death, yet they reduce deaths. To refute the activists, the columnist would need to show that cable lines do not raise the rate. Showing the rate is not zero without them proves nothing.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Look for "it won't solve the whole problem" being treated as "it won't help."$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT149-S4-Q14$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$The columnist is not reversing a conditional. The error is about how much a proposal must accomplish.$batch02$), ($batch02$B$batch02$, $batch02$Some electrocutions without overhead cable lines show only that the ban would not end electrocution entirely. The activists only claimed the lines raise the risk. Rejecting their argument because it does not solve everything holds them to a standard they never claimed.$batch02$), ($batch02$C$batch02$, $batch02$The columnist rejects one argument for the ban. Other benefits the ban might have are beside the point of whether *this* argument works.$batch02$), ($batch02$D$batch02$, $batch02$The columnist says nothing about the activists themselves.$batch02$), ($batch02$E$batch02$, $batch02$No other proposals are mentioned.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT149-S4-Q14$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
